/* Master (left, USB-C side): portrait so Luna renders upright.
 * Slave (right): keep whatever crkbd set (180), so the corne logo is unchanged. */
oled_rotation_t oled_init_user(oled_rotation_t rotation) {
    if (is_keyboard_master()) {
        return OLED_ROTATION_270;
    }
    return rotation;
}

